/* @lc app=leetcode id=3873 lang=kotlin */ class Solution { fun find(p: IntArray, x: Int): Int = generateSequence(x) { if (p[it] == it) null else p[it] }.toList().let { path -> path.last().also { r -> path.forEach { p[it] = r } } } fun maxActivated(points: Array<IntArray>): Int = points.map { it[0] }.distinct().let { xs -> points.map { it[1] }.distinct().let { ys -> IntArray(xs.size + ys.size) { it }.let { p -> points.forEach { (x, y) -> p[find(p, xs.indexOf(x))] = find(p, xs.size + ys.indexOf(y)) } .let { points.groupingBy { find(p, xs.indexOf(it[0])) }.eachCount().values.sortedDescending().let { c -> c[0] + (c.getOrNull(1) ?: 0) + 1 } } } } } }